CREATE UNIQUE INDEX attendee_users_phone_unique ON attendee_users (CASE WHEN length(replace(replace(replace(replace(replace(phone,' ',''),'+',''),'(',''),')',''),'-',''))=12 AND substr(replace(replace(replace(replace(replace(phone,' ',''),'+',''),'(',''),')',''),'-',''),1,2)='91' AND substr(replace(replace(replace(replace(replace(phone,' ',''),'+',''),'(',''),')',''),'-',''),3,1) GLOB '[6-9]' THEN substr(replace(replace(replace(replace(replace(phone,' ',''),'+',''),'(',''),')',''),'-',''),3) ELSE replace(replace(replace(replace(replace(phone,' ',''),'+',''),'(',''),')',''),'-','') END);
